-- EWU StudyHub Update 0066 — Help/Guide content polish + role-aware Student access
-- Goals: concise modern Bangla, clear English UI terms, less repetition, and accurate Guest/Student/Seller/Admin access.

do $$ begin
  if exists (select 1 from pg_constraint where conname = 'guide_sections_required_access_check') then alter table public.guide_sections drop constraint guide_sections_required_access_check; end if;
  if exists (select 1 from pg_constraint where conname = 'guide_overview_items_required_access_check') then alter table public.guide_overview_items drop constraint guide_overview_items_required_access_check; end if;
end $$;

alter table public.guide_sections add constraint guide_sections_required_access_check check (required_access in ('none','authenticated_student','verified_student','seller','admin'));
alter table public.guide_overview_items add constraint guide_overview_items_required_access_check check (required_access in ('none','authenticated_student','verified_student','seller','admin'));

